export const FIELD={w:1000,h:600,x:142,y:91,cw:87,ch:84,cols:8,rows:5};
export const UNITS={
 pulse:{name:'센트리',tag:'기관포',cost:100,hp:180,damage:16,rate:.72,color:'#79d8de',unlock:0,desc:'빠른 연사 · 기본 방어의 중심'},
 frost:{name:'프로스트',tag:'냉각포',cost:125,hp:155,damage:9,rate:1.15,color:'#8baeff',unlock:1,desc:'이동 속도 55% 감소 · 돌진 저지'},
 mortar:{name:'벌컨',tag:'박격포',cost:190,hp:210,damage:68,rate:2.2,color:'#f8a85b',unlock:2,desc:'장갑 관통 · 주변 적까지 폭발'},
 wall:{name:'배스천',tag:'방벽',cost:60,hp:700,damage:0,rate:0,color:'#b0bac8',unlock:0,desc:'튼튼한 장갑 · 전선을 붙잡는 방벽'},
 reactor:{name:'다이너모',tag:'발전기',cost:85,hp:125,damage:0,rate:0,color:'#b7db84',unlock:0,desc:'6초마다 에너지 +22 · 후방에 배치'}
};
export const ENEMIES={scout:{name:'정찰 로봇',hp:78,speed:17,damage:18,reward:15},runner:{name:'돌진 로봇',hp:60,speed:36,damage:14,reward:17},armor:{name:'중장갑 로봇',hp:240,speed:11,damage:32,reward:30,armor:.48},support:{name:'실드 드론',hp:155,speed:13,damage:16,reward:28},boss:{name:'골리앗',hp:2400,speed:7,damage:65,reward:180,armor:.25}};
const wave=(types,lanes,gap=3)=>types.map((type,i)=>({type,lane:lanes[i%lanes.length],at:i*gap}));
const seq=(n,pattern)=>Array.from({length:n},(_,i)=>pattern[i%pattern.length]);
export const STAGES=[
 {name:'첫 번째 신호',zone:'OUTPOST / 07',sub:'잠들어 있던 기지에 정찰대가 접근합니다.',tip:'중앙 세 줄에 센트리를 하나씩. 발전기는 후방에 설치하세요.',color:'#76c9c9',lanes:[1,2,3],energy:340,waves:[wave(seq(5,['scout']),[2],4),wave(seq(9,['scout']),[1,3,2],3.5),wave(seq(12,['scout']),[3,1,2],2.8)]},
 {name:'붉은 모래 폭풍',zone:'DUST FRONT / 12',sub:'빠른 돌진 부대가 양쪽 측면으로 침투합니다.',tip:'모든 줄을 방어하세요. 냉각포가 빠른 적을 붙잡아 줍니다.',color:'#e6a16a',lanes:[0,1,2,3,4],energy:520,waves:[wave(seq(10,['scout','runner','scout']),[0,4,2,1,3],3),wave(seq(14,['runner','scout','runner']),[3,0,4,1,2],2.6),wave(seq(17,['runner','scout']),[4,2,0,3,1],2.3),wave(seq(19,['scout','runner','runner']),[0,1,2,3,4],2)]},
 {name:'강철의 행진',zone:'FOUNDRY / 03',sub:'주조 공장에서 중장갑 부대가 출격합니다.',tip:'벌컨의 폭발은 장갑을 무시합니다. 방벽 뒤에서 포격하세요.',color:'#ef9860',lanes:[0,1,2,3,4],energy:640,waves:[wave(seq(10,['scout','armor','scout']),[1,3,2,0,4],3.4),wave(seq(14,['armor','scout','runner']),[0,2,4,1,3],2.8),wave(seq(16,['scout','armor','armor']),[4,3,2,1,0],2.7),wave(seq(18,['armor','runner','scout']),[2,0,4,1,3],2.2)]},
 {name:'침묵의 회로',zone:'BLACK GRID / 09',sub:'지원 드론의 보호막이 적의 전열을 감쌉니다.',tip:'실드 드론 주변 적은 피해를 덜 받습니다. 궤도 폭격으로 함께 처리하세요.',color:'#ab97e6',lanes:[0,1,2,3,4],energy:720,waves:[wave(seq(12,['support','scout','runner']),[2,2,2,0,4,1,3],2.8),wave(seq(16,['armor','support','scout','runner']),[0,0,0,4,4,4,2,1,3],2.5),wave(seq(18,['runner','support','armor']),[0,2,4,1,3],2.2),wave(seq(19,['support','armor','runner','scout']),[1,1,3,3,0,2,4],2),wave(seq(21,['armor','support','runner']),[0,1,2,3,4],1.9)]},
 {name:'최후의 방어선',zone:'CORE SECTOR / 00',sub:'골리앗이 접근합니다. 이곳이 마지막 방어선입니다.',tip:'포탑을 강화하고 후방 발전기를 지키세요. 골리앗은 포탑에 미사일을 발사합니다.',color:'#ed7b71',lanes:[0,1,2,3,4],energy:820,waves:[wave(seq(14,['runner','scout','armor']),[0,1,2,3,4],2.7),wave(seq(18,['support','armor','runner']),[2,0,4,1,3],2.4),wave(seq(21,['armor','runner','runner']),[4,3,2,1,0],2.1),wave(seq(23,['support','armor','runner','scout']),[0,0,4,4,1,2,3],1.9),[{type:'boss',lane:2,at:8},...wave(seq(25,['runner','armor','support','scout']),[0,4,1,3,2],2.5)]]}
];
export const position=(col,row)=>({x:FIELD.x+(col+.5)*FIELD.cw,y:FIELD.y+(row+.5)*FIELD.ch});
export class Battle{
 constructor(stage=0){this.stage=stage;this.config=STAGES[stage];this.energy=this.config.energy;this.hp=100;this.towers=[];this.enemies=[];this.shots=[];this.events=[];this.wave=0;this.queue=[];this.waveTime=0;this.time=0;this.intermission=0;this.phase='prep';this.kills=0;this.cooldown=0;this.id=0;this.spent=0;this.strikes=0;}
 emit(type,data={}){this.events.push({type,...data});}
 towerAt(col,row){return this.towers.find(t=>t.col===col&&t.row===row)}
 build(type,col,row){const u=UNITS[type];if(!['prep','fight','break'].includes(this.phase)||!u||u.unlock>this.stage||!Number.isInteger(col)||!Number.isInteger(row)||col<0||col>=8||!this.config.lanes.includes(row)||this.towerAt(col,row)||this.energy<u.cost)return false;this.energy-=u.cost;this.spent+=u.cost;this.towers.push({id:++this.id,type,col,row,...position(col,row),hp:u.hp,maxHp:u.hp,level:1,cd:.15,income:6,recoil:0,flash:0});this.emit('build',{...position(col,row),color:u.color});return true;}
 upgrade(id){const t=this.towers.find(t=>t.id===id);if(!t||t.level>=3||['won','lost'].includes(this.phase))return false;const cost=this.upgradeCost(t);if(this.energy<cost)return false;this.energy-=cost;this.spent+=cost;t.level++;t.maxHp=Math.round(UNITS[t.type].hp*(1+.5*(t.level-1)));t.hp=t.maxHp;this.emit('upgrade',{x:t.x,y:t.y,color:UNITS[t.type].color});return true;}
 upgradeCost(t){return Math.round(UNITS[t.type].cost*(.65+.3*(t.level-1)))}
 sell(id){const t=this.towers.find(t=>t.id===id);if(!t||['won','lost'].includes(this.phase))return false;this.energy+=Math.floor(UNITS[t.type].cost*.6);this.towers=this.towers.filter(x=>x!==t);this.emit('sell',{x:t.x,y:t.y});return true;}
 launch(){if(!['prep','break'].includes(this.phase)||this.wave>=this.config.waves.length)return false;if(this.phase==='break'&&this.intermission>1){const bonus=Math.floor(this.intermission*2);this.energy+=bonus;this.emit('income',{x:500,y:62,value:bonus})}this.queue=this.config.waves[this.wave].map(e=>({...e})).sort((a,b)=>a.at-b.at);this.wave++;this.waveTime=0;this.phase='fight';this.emit('wave',{wave:this.wave});return true;}
 strike(x,y){if(this.stage<1||this.cooldown>0||this.phase!=='fight'||!Number.isFinite(x)||!Number.isFinite(y))return false;this.cooldown=38;this.strikes++;for(const e of this.enemies)if(Math.hypot(e.x-x,e.y-y)<135)this.hit(e,230,true);this.emit('strike',{x,y});return true;}
 hit(e,damage,pierce=false){if(e.hp<=0)return;const shield=this.enemies.some(s=>s.type==='support'&&s.hp>0&&s!==e&&Math.hypot(s.x-e.x,s.y-e.y)<140);const value=damage*(pierce?1:1-(ENEMIES[e.type].armor||0))*(shield?.6:1);e.hp-=value;e.flash=.09;if(e.hp<=0){this.energy+=ENEMIES[e.type].reward;this.kills++;this.emit('kill',{x:e.x,y:e.y,boss:e.type==='boss',value:ENEMIES[e.type].reward});}else this.emit('hit',{x:e.x,y:e.y});}
 step(dt){if(!['fight','break'].includes(this.phase))return;dt=Math.min(.1,Math.max(0,dt));this.time+=dt;this.energy=Math.min(9999,this.energy+dt*7);this.cooldown=Math.max(0,this.cooldown-dt);
 if(this.phase==='break'){this.intermission-=dt;if(this.intermission<=0)this.launch()}
 if(this.phase==='fight'){this.waveTime+=dt;while(this.queue.length&&this.queue[0].at<=this.waveTime){const a=this.queue.shift(),u=ENEMIES[a.type],maxHp=u.hp*(1+this.stage*.07);this.enemies.push({id:++this.id,type:a.type,row:a.lane,x:1005,y:position(0,a.lane).y,hp:maxHp,maxHp,cd:.5,missile:9,slow:0,flash:0,walk:0});if(a.type==='boss')this.emit('boss');}}
 for(const t of this.towers){t.recoil=Math.max(0,t.recoil-dt*6);t.flash=Math.max(0,t.flash-dt);if(t.type==='reactor'){t.income-=dt;if(t.income<=0){t.income+=6;const value=22+12*(t.level-1);this.energy+=value;this.emit('income',{x:t.x,y:t.y-27,value})}continue}const u=UNITS[t.type];if(!u.damage)continue;t.cd-=dt;if(t.cd>0)continue;const target=this.enemies.filter(e=>e.hp>0&&e.row===t.row&&e.x>t.x-26&&e.x-t.x<(t.type==='mortar'?610:t.type==='frost'?430:470)).sort((a,b)=>a.x-b.x)[0];if(target){t.cd=u.rate/(1+.15*(t.level-1));t.recoil=1;this.shots.push({type:t.type,x:t.x+26,y:t.y-8,sx:t.x+26,sy:t.y-8,tx:target.x,ty:target.y,target:target.id,damage:u.damage*(1+.65*(t.level-1)),age:0,duration:t.type==='mortar'?.55:.15});this.emit('shoot',{x:t.x+28,y:t.y-8,weapon:t.type})}}
 for(const s of this.shots){s.age+=dt;const target=this.enemies.find(e=>e.id===s.target&&e.hp>0);if(target){s.tx=target.x;s.ty=target.y}if(s.age>=s.duration){if(s.type==='mortar'){this.enemies.filter(e=>e.hp>0&&Math.hypot(e.x-s.tx,e.y-s.ty)<100).forEach(e=>this.hit(e,s.damage,true));this.emit('blast',{x:s.tx,y:s.ty})}else if(target){this.hit(target,s.damage);if(s.type==='frost')target.slow=2.6;}s.done=true;}}
 this.shots=this.shots.filter(s=>!s.done);
 for(const e of this.enemies){if(e.hp<=0)continue;e.slow=Math.max(0,e.slow-dt);e.flash=Math.max(0,e.flash-dt);e.walk+=dt*(e.slow>0?2:6);e.cd-=dt;const victim=this.towers.filter(t=>t.hp>0&&t.row===e.row&&e.x-t.x<47&&e.x-t.x>-35).sort((a,b)=>b.x-a.x)[0];if(victim){if(e.cd<=0){victim.hp-=ENEMIES[e.type].damage;victim.flash=.15;e.cd=.85;this.emit('bite',{x:victim.x,y:victim.y})}}else e.x-=ENEMIES[e.type].speed*dt*(e.slow>0?.45:1);
 if(e.type==='boss'){e.missile-=dt;if(e.missile<=0){e.missile=8;const targets=this.towers.filter(t=>t.hp>0).sort((a,b)=>b.x-a.x).slice(0,3);for(const t of targets){t.hp-=55;this.emit('missile',{x:t.x,y:t.y,fromX:e.x,fromY:e.y})}}}
 if(e.x<95){this.hp=Math.max(0,this.hp-(e.type==='boss'?100:e.type==='armor'?20:10));e.hp=0;this.emit('breach',{x:95,y:e.y})}}
 for(const t of this.towers)if(t.hp<=0)this.emit('destroy',{x:t.x,y:t.y});this.towers=this.towers.filter(t=>t.hp>0);this.enemies=this.enemies.filter(e=>e.hp>0);
 if(this.hp<=0){this.phase='lost';this.emit('lost');return}
 if(this.phase==='fight'&&!this.queue.length&&!this.enemies.length){if(this.wave===this.config.waves.length){this.phase='won';this.emit('won',{stars:this.stars()})}else{this.phase='break';this.intermission=12;this.energy+=90+this.wave*20;this.emit('clear',{bonus:90+this.wave*20})}}
 }
 stars(){return this.hp>=90?3:this.hp>=50?2:1;}
}
